                break
            except Exception:
                pass
        elif isinstance(val, (int, float)):
            # sometimes a scalar target; map to an offset
            try:
                target = (float(val), float(val))
                break
            except Exception:
                pass

    # If we have a target, compute a delta towards it (clamped to -1..1)
    if target is not None:
        dx = target[0] - x
        dy = target[1] - y
        if dx > 1: dx = 1
        elif dx < -1: dx = -1
        else: dx = int(dx)
        if dy > 1: dy = 1
        elif dy < -1: dy = -1
        else: dy = int(dy)
        return [dx, dy]

